diff --git a/src/auth/permissions.ts b/src/auth/permissions.ts
@@ -0,0 +1,14 @@
+export function canAccessResource(user: User, resource: Resource): boolean {
+  if (user.role === "admin") {
+    return true;
+  }
+  if (resource.ownerId === user.id) {
+    return true;
+  }
+  if (user.role === "viewer" && resource.visibility === "public") {
+    return true;
+  }
+  return false;
+}
